    const renderAssessments = () => <><Head title={role === 'student' ? 'واجباتي وتقييماتي' : 'مركز التقييم والواجبات'} sub="نواتج التعلم هي المرجع للأنشطة ومعايير التصحيح."/><div className={cx("stats three")}><Stat label="أنشطة تم تسليمها" value={fmt(Object.keys(d.assignments).filter(id => role !== 'instructor' || myCourses.some(c => c.id === id)).length)} note="تسليماتك في هذه التجربة" icon={FileText}/><Stat label="بانتظار المراجعة" value={fmt(Object.keys(d.assignments).filter(id => role !== 'instructor' || myCourses.some(c => c.id === id)).filter(id => !(d.grades[id] >= 0)).length)} note="تحتاج تقييم المحاضر" icon={Clock} color="orange"/><Stat label="تقييمات مكتملة" value={fmt(Object.entries(d.grades).filter(([id, g]) => g >= 0 && (role !== 'instructor' || myCourses.some(c => c.id === id))).length)} note="وفق معيار التقدير التجريبي" icon={ClipboardCheck} color="green"/></div><div className={cx("panel")}><div className={cx("panel-head")}><h2>الأنشطة التطبيقية</h2><Badge color="purple">معايير تقدير واضحة</Badge></div>{Object.keys(d.assignments).filter(id => role !== 'instructor' || myCourses.some(c => c.id === id)).length ? Object.entries(d.assignments).filter(([id]) => role !== 'instructor' || myCourses.some(c => c.id === id)).map(([id, text]) => <div className={cx("feedback")} key={id}><div className={cx("row-between")}><h3>{d.courses.find(c => c.id === id)?.title}</h3><Badge color={d.grades[id] >= 0 ? 'green' : 'orange'}>{d.grades[id] >= 0 ? d.grades[id] + ' / 100' : 'بانتظار المراجعة'}</Badge></div><p className={cx("my-3")}>{text}</p>{role !== 'student' && <Btn small onClick={() => { setSelected(id); setGrade(d.grades[id] >= 0 ? String(d.grades[id]) : '85'); setModal('grade'); }}>مراجعة وتصحيح<ClipboardCheck size={15}/></Btn>}</div>) : <div className={cx("empty")}><ClipboardCheck className={cx("mx-auto mb-3")} size={30}/><p>لا توجد تسليمات حتى الآن.</p><p className={cx("small mt-2")}>افتح درسًا وسلّم النشاط، ثم راجعه من دور المحاضر.</p><Btn disabled={!canPreviewRoles} disabledReason="معاينة الأدوار متاحة لمدير التدريب. تواصل معه لتجربتها." onClick={() => openCourse('data', true)}>افتح نشاطًا للتجربة</Btn></div>}</div></>;
    const placementQuestions = [{ q: 'ما أفضل بداية لبناء لوحة مؤشرات؟', options: ['اختيار الألوان', 'تحديد القرار والمقاييس', 'إضافة كل البيانات'], correct: 1 }, { q: 'كيف تتعامل مع ناتج الذكاء الاصطناعي؟', options: ['أراجعه وأتحقق من مصادره', 'أعتمده دائمًا', 'أحذف المصدر'], correct: 0 }, { q: 'ما فائدة توثيق خطوات تنظيف البيانات؟', options: ['زيادة حجم الملف', 'تغيير البيانات دون مراجعة', 'إتاحة التحقق وإعادة إنتاج النتائج'], correct: 2 }];
    const renderPlacement = () => <><Head title="اختبار تحديد المستوى" sub="تشخيص أولي للمهارات الرقمية · ٣ أسئلة · لا يُحتسب ضمن الدرجة النهائية"/><div className={cx("detail-grid")}><div className={cx("panel")}>{d.placement !== null && !placing ? <><Badge color="green">اكتمل الاختبار التجريبي</Badge><h2 className={cx("my-5")}>نتيجتك {fmt(d.placement)} من ٣</h2><p className={cx("muted my-3")}>{d.placement >= 2 ? 'لديك أساس مناسب. ابدأ بمسار المهارات الرقمية وانتقل للتطبيق العملي.' : 'ننصح بالبدء بدورة Excel وبناء أساس واضح قبل التوسع في التحليل.'}</p><div className={cx("row")}><Btn primary onClick={() => { setPathId('digital'); go('path'); }}>استعرض المسار المقترح</Btn><Btn onClick={() => { setPlacing(true); setPlaceAnswers({}); }}>إعادة التجربة</Btn></div></> : placing ? <>{placementQuestions.map((q, qi) => <div key={q.q} className={cx("mb-6")}><h3>{qi + 1}. {q.q}</h3>{q.options.map((o, i) => <button key={o} className={cx('quiz-option ' + (placeAnswers[qi] === i ? 'selected' : ''))} onClick={() => setPlaceAnswers({ ...placeAnswers, [qi]: i })}>{o}</button>)}</div>)}<Btn primary disabled={Object.keys(placeAnswers).length < 3} disabledReason="أجب عن الأسئلة الثلاثة لعرض النتيجة والتوصية." onClick={() => { update({ placement: placementQuestions.filter((q, i) => placeAnswers[i] === q.correct).length }); setPlacing(false); }}>اعرض النتيجة والتوصية</Btn></> : <div className={cx("text-center py-10")}><Target size={46} className={cx("mx-auto text-primary mb-5")}/><h2>ما نقطة البداية المناسبة لك؟</h2><p className={cx("muted my-4")}>أسئلة قصيرة عن فهم البيانات والتعامل الآمن مع الذكاء الاصطناعي.</p><Btn primary onClick={() => setPlacing(true)}>ابدأ الاختبار<ArrowLeft size={16}/></Btn></div>}</div><div className={cx("panel")}><h3>كيف تستخدم النتيجة؟</h3><ul className={cx("policy-list")}><li>التوصية استرشادية في النموذج.</li><li>لا تغيّر تسجيلاتك أو مدفوعاتك.</li><li>في النسخة النهائية تُربط بمصفوفة مهارات معتمدة من مسؤول البرنامج.</li></ul></div></div></>;
    const renderWaitlist = () => <><Head title="قائمة الانتظار" sub="اهتمام بالالتحاق ← مراجعة القبول ← التسجيل المعتمد ← إتاحة التعلم"/><div className={cx("panel")}><h2>مسار المهارات الرقمية للمستقبل</h2>{d.waitlist.map(name => <div className={cx("module-row")} key={name}><div className={cx("row")}><div className={cx("avatar")}>{name.slice(0, 1)}</div><div><h3>{name}</h3><small>طلب تجريبي · بانتظار التواصل</small></div></div><Btn small onClick={() => { update({ waitlist: d.waitlist.filter(n => n !== name), admitted: [...d.admitted, name] }); toast.success('نُقل إلى قائمة مراجعة القبول داخل النموذج فقط.'); }}>إحالة لمراجعة القبول</Btn></div>)}{!d.waitlist.length && <div className={cx("empty")}>لا توجد طلبات انتظار متبقية.</div>}{d.admitted.length > 0 && <div className={cx("note success")}>قيد مراجعة القبول: {d.admitted.join('، ')}. لم يُنشأ تسجيل أو تأكيد دفع.</div>}</div></>;
